/**
 * The playable sets.
 *
 * A set is a group of places that share a map, a flag for each, and a way of
 * being divided up — countries of the world grouped by continent, or US states
 * grouped by region. Modes are written against this shape and never against
 * countries specifically, so a new set is a build script and an entry here.
 *
 * Each set's data is generated by the matching tool and committed under
 * data/sets/<id>/. Nothing in the game hardcodes a place name or code.
 */

export const SETS = [
  {
    id: 'world',
    title: 'Countries of the world',
    blurb: 'All 193 UN member states.',
    noun: 'country',
    plural: 'countries',
    groupLabel: 'Part of the world',
    flags: 'assets/flags/world',
  },
  {
    id: 'usa',
    title: 'The United States',
    blurb: 'The 50 states, their flags and capitals.',
    noun: 'state',
    plural: 'states',
    groupLabel: 'Part of the country',
    flags: 'assets/flags/usa',
  },
];

export const setById = (id) => SETS.find((s) => s.id === id) ?? SETS[0];

const cache = new Map();

async function loadJson(path) {
  const response = await fetch(path);
  if (!response.ok) throw new Error(`Could not load ${path} (HTTP ${response.status})`);
  return response.json();
}

/** A set's places. Loaded once per set. */
export async function loadEntries(set) {
  const key = `${set.id}:entries`;
  if (!cache.has(key)) cache.set(key, await loadJson(`data/sets/${set.id}/entries.json`));
  return cache.get(key);
}

/** A set's geometry. Only the map modes ask for it, and only once. */
export async function loadMap(set) {
  const key = `${set.id}:map`;
  if (!cache.has(key)) cache.set(key, await loadJson(`data/sets/${set.id}/map.json`));
  return cache.get(key);
}

/** The groups a set can be narrowed to, in a stable order, 'All' first. */
export const groupsOf = (entries) => [
  'All',
  ...[...new Set(entries.map((e) => e.group))].sort(),
];

/** Entries in a group, or all of them. */
export const inGroup = (entries, group) =>
  group === 'All' ? entries : entries.filter((e) => e.group === group);

/** Path to a place's flag. */
export const flagUrl = (set, entry) => `${set.flags}/${entry.code}.svg`;
